        return;
    }

    pdf_obj *enc_obj = pdf_get_obj(pdf, pdf->encryption_obj_id);
    size_t enc_obj_size = pdf_obj_size(pdf, enc_obj);

    int encrypt_metadata = pdf_obj_get_int(pdf, enc_obj, "/EncryptMetadata", 1);
    int p_value = pdf_obj_get_int(pdf, enc_obj, "/P", 0);
    int r_value = pdf_obj_get_int(pdf, enc_obj, "/R", 4);
    int length = pdf_obj_get_int(pdf, enc_obj, "/Length", 128);

    if (r_value < 2 || r_value > 5) {
        return;
    }

    if (length != 40 && length != 128 && length != 256) {
        return;
    }

    pdf_obj *o_str = pdf_obj_get(pdf, enc_obj, "/O");
    pdf_obj *u_str = pdf_obj_get(pdf, enc_obj, "/U");

    if (!o_str || !u_str) {
        return;
    }

    size_t o_len = pdf_obj_string_length(pdf, o_str);
    size_t u_len = pdf_obj_string_length(pdf, u_str);

    if (o_len != (size_t)length || u_len != (size_t)length) {
        return;
    }

    char *o_val = pdf_obj_string_value(pdf, o_str);
    char *u_val = pdf_obj_string_value(pdf, u_str);

    // Log encryption parameters
    fprintf(stderr, "Encryption: /P=%d /R=%d /Length=%d /EncryptMetadata=%d\n", p_value, r_value, length, encrypt_metadata);
    fprintf(stderr, "/O length: %zu /U length: %zu\n", o_len, u_len);

    // Verify user password
    verify_user_password(pdf, u_val, p_value, r_value, length);

    free(o_val);
    free(u_val);
}

