void handle_encryption_settings(struct pdf_struct *pdf) {
    if (!pdf->encryption_object_id_valid || !pdf->file_id_present) {
        return;
    }

    pdf_obj *encrypt_obj = pdf_get_obj(pdf, pdf->encryption_object_id);
    size_t encrypt_obj_size = pdf_obj_size(pdf, encrypt_obj);
    int encrypt_metadata = pdf_dict_get_int(pdf, encrypt_obj, "/EncryptMetadata");
    int p = pdf_dict_get_int(pdf, encrypt_obj, "/P");
    int r = pdf_dict_get_int(pdf, encrypt_obj, "/R");
    int length = pdf_dict_get_int(pdf, encrypt_obj, "/Length");

    if (r < 2 || r > 5) {
        return; // Invalid /R value
    }

    if (length != 40 && length != 128 && length != 256) {
        return; // Invalid /Length value
    }

    pdf_obj *o = pdf_dict_get(pdf, encrypt_obj, "/O");
    pdf_obj *u = pdf_dict_get(pdf, encrypt_obj, "/U");

    if (!o || !u) {
        return; // Missing /O or /U
    }

    size_t o_len = pdf_obj_length(pdf, o);
    size_t u_len = pdf_obj_length(pdf, u);

    if (o_len != 16 && o_len != 32 && o_len != 48) {
        return; // Invalid /O length
    }

    if (u_len != 16 && u_len != 32) {
        return; // Invalid /U length
    }

    char *o_str = pdf_obj_to_string(pdf, o);
    char *u_str = pdf_obj_to_string(pdf, u);

    if (!o_str || !u_str) {
        return; // Failed to extract strings
    }

    // Log encryption parameters
    fprintf(stderr, "Encryption parameters: /R=%d, /Length=%d, /P=%d, /EncryptMetadata=%d\n", r, length, p, encrypt_metadata);

    // Verify user password
    verify_user_password(pdf, o_str, u_str);

    // Free allocated memory
    free(o_str);
    free(u_str);
}

